// 确定性战斗 tick 与伤害管线（纯逻辑，无 DOM）
// 契约来源：docs/architecture/architecture.md 战斗契约
export const TICK_HZ = 60;
export const TICK_MS = 1000 / TICK_HZ;

// 多人缩放查表（单人基准=1.0）
export const MULTIPLAYER_SCALE = {
  1: { hp: 1.0, dmg: 1.0, gold: 1.0 },
  2: { hp: 1.6, dmg: 1.15, gold: 1.25 },
  3: { hp: 2.1, dmg: 1.25, gold: 1.45 },
  4: { hp: 2.6, dmg: 1.35, gold: 1.65 },
};
export const BOSS_EXTRA_HP = 0.1;

export function getScale(playerCount, isBoss = false) {
  const n = Math.max(1, Math.min(4, playerCount | 0));
  const base = MULTIPLAYER_SCALE[n];
  return {
    hp: base.hp * (isBoss ? 1 + BOSS_EXTRA_HP : 1),
    dmg: base.dmg,
    gold: base.gold,
  };
}

// 固定步长累加器：把真实 dt 切成整数 tick，保证确定性
export class FixedStepClock {
  constructor(hz = TICK_HZ) {
    this.stepMs = 1000 / hz;
    this.acc = 0;
    this.tick = 0;
  }
  // 返回本次应执行的 tick 数
  advance(dtMs) {
    if (!Number.isFinite(dtMs) || dtMs < 0) throw new Error('dtMs must be >= 0');
    this.acc += dtMs;
    let n = 0;
    while (this.acc >= this.stepMs) {
      this.acc -= this.stepMs;
      this.tick++;
      n++;
    }
    return n;
  }
}

// 伤害管线：顺序固定，便于复现与测试
// 1 基础攻击 2 词条加成 3 暴击 4 防御减免 5 多人缩放
export function computeDamage({
  baseAttack,
  flatBonus = 0,
  percentBonus = 0,
  critChance = 0,
  critMultiplier = 1.5,
  defense = 0,
  playerCount = 1,
  isBoss = false,
  rng = Math.random,
}) {
  if (!Number.isFinite(baseAttack) || baseAttack < 0) throw new Error('baseAttack invalid');
  let dmg = baseAttack + flatBonus;
  dmg *= 1 + percentBonus;
  const crit = rng() < critChance;
  if (crit) dmg *= critMultiplier;
  // 防御减免：递减公式，防御>=100 时最多减 50%
  const reduction = defense / (defense + 100);
  dmg *= 1 - reduction;
  dmg *= getScale(playerCount, isBoss).dmg;
  return { damage: Math.max(1, Math.round(dmg)), crit };
}

// 受击顿帧与闪白时长（毫秒），供表现层读取
export const HIT_FEEL = { hitStopMs: 80, flashMs: 120, shakeMs: 100 };

// 掉落系统：品质权重、Boss 保底、装备独立分桶（纯逻辑）
export const QUALITY = ['white', 'green', 'blue', 'purple', 'orange'];
export const QUALITY_WEIGHT = { white: 40, green: 30, blue: 20, purple: 8, orange: 2 };
export const BOSS_GUARANTEE = { minQuality: 'blue', purpleChance: 0.2, orangeChance: 0.05 };

function weightedPick(rng) {
  const total = Object.values(QUALITY_WEIGHT).reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (const q of QUALITY) {
    r -= QUALITY_WEIGHT[q];
    if (r < 0) return q;
  }
  return 'white';
}

// 普通掉落
export function rollQuality(rng = Math.random) {
  return weightedPick(rng);
}

// Boss 掉落：保底蓝，紫/橙按概率覆盖
export function rollBossQuality(rng = Math.random) {
  if (rng() < BOSS_GUARANTEE.orangeChance) return 'orange';
  if (rng() < BOSS_GUARANTEE.purpleChance) return 'purple';
  return BOSS_GUARANTEE.minQuality;
}

// 装备独立分桶：按玩家 id 稳定哈希，保证每人只看到自己的光柱
export function bucketForPlayer(playerId) {
  const s = String(playerId);
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) % 1000;
}

// 生成一次掉落事件；shared=true 表示金币/材料共享
export function rollDrop({ playerId, isBoss = false, rng = Math.random }) {
  const quality = isBoss ? rollBossQuality(rng) : rollQuality(rng);
  return {
    playerId,
    bucket: bucketForPlayer(playerId),
    quality,
    shared: false,
  };
}

export function rollSharedDrop({ gold = 0, material = 0 }) {
  return { gold, material, shared: true };
}

// 房间生成与不变量校验（纯逻辑，种子可复现）
export const ROOM_TYPES = ['combat', 'platform', 'treasure', 'shop', 'campfire', 'event', 'elite', 'boss'];

// 简单可复现 PRNG（mulberry32）
export function makeRng(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 生成一层房间图：8-12 房间 + 1 Boss 房
export function generateFloor(seed) {
  const rng = makeRng(seed);
  const count = 8 + Math.floor(rng() * 5); // 8..12
export const _unused = 0;
  const rooms = [];
  for (let i = 0; i < count; i++) {
    rooms.push({ id: i, type: 'combat', doors: [] });
  }
  // 主路径：0..count-1 线性连通
  for (let i = 0; i < count - 1; i++) {
    rooms[i].doors.push(i + 1);
    rooms[i + 1].doors.push(i);
  }
  // 固定 1 篝火 1 商店
  rooms[1].type = 'campfire';
  rooms[2].type = 'shop';
  // 宝箱房 2-4
  const treasureCount = 2 + Math.floor(rng() * 3);
  let placed = 0;
  for (let i = 3; i < count - 1 && placed < treasureCount; i++) {
    if (rooms[i].type === 'combat') { rooms[i].type = 'treasure'; placed++; }
  }
  // 精英房概率 60%
  if (rng() < 0.6) {
    for (let i = 3; i < count - 1; i++) {
      if (rooms[i].type === 'combat') { rooms[i].type = 'elite'; break; }
    }
  }
  // Boss 房
  rooms.push({ id: count, type: 'boss', doors: [count - 1] });
  rooms[count - 1].doors.push(count);
  const floor = { seed, rooms, bossId: count };
  validateFloor(floor);
  return floor;
}

// 不变量校验：主路径连通、1 篝火 1 商店、钥匙门<=1、Boss 可达
export function validateFloor(floor) {
  const { rooms, bossId } = floor;
  const campfires = rooms.filter(r => r.type === 'campfire').length;
  const shops = rooms.filter(r => r.type === 'shop').length;
  if (campfires !== 1) throw new Error('floor must have exactly 1 campfire');
  if (shops !== 1) throw new Error('floor must have exactly 1 shop');
  // BFS 从入口 0 到 boss
  const seen = new Set([0]);
  const q = [0];
  while (q.length) {
    const cur = q.shift();
    for (const d of rooms[cur].doors) {
      if (!seen.has(d)) { seen.add(d); q.push(d); }
    }
  }
  if (!seen.has(bossId)) throw new Error('boss unreachable from entrance');
  return true;
}

// 存档信封：版本号 + CRC32 + 双备份 + 迁移链（纯逻辑）
export const SAVE_VERSION = 1;

export function crc32(str) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < str.length; i++) {
    crc ^= str.charCodeAt(i);
    for (let j = 0; j < 8; j++) {
      crc = (crc >>> 1) ^ (0xEDB88320 & -(crc & 1));
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

export function makeEnvelope(payload, version = SAVE_VERSION) {
  const body = JSON.stringify(payload);
  return { version, crc: crc32(body), body };
}

export function verifyEnvelope(env) {
  if (!env || typeof env.body !== 'string') return false;
  return crc32(env.body) === env.crc;
}

// 迁移链：旧版本 -> 新版本
export const MIGRATIONS = {
  1: (p) => p,
};

export function migrate(env) {
  if (!verifyEnvelope(env)) throw new Error('save corrupted (crc mismatch)');
  let v = env.version;
  let payload = JSON.parse(env.body);
  while (v < SAVE_VERSION) {
    const fn = MIGRATIONS[v];
    if (!fn) throw new Error('no migration from version ' + v);
    payload = fn(payload);
    v++;
  }
  return payload;
}

// 双备份写入（介质由调用方注入，浏览器用 localStorage）
export function saveDual(storage, key, payload) {
  const env = makeEnvelope(payload);
  const raw = JSON.stringify(env);
  storage.setItem(key + '.a', raw);
  storage.setItem(key + '.b', raw);
  return env;
}

export function loadDual(storage, key) {
  for (const suffix of ['.a', '.b']) {
    const raw = storage.getItem(key + suffix);
    if (!raw) continue;
    try {
      const env = JSON.parse(raw);
      if (verifyEnvelope(env)) return migrate(env);
    } catch (e) { /* try next backup */ }
  }
  return null;
}
